// Default login page. Replace this file to own the whole presentation.
import { isValidPassword } from "@alwith/module-auth"
import { type ReactNode, useEffect, useState } from "react"
import { useTranslation } from "react-i18next"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Field, FieldDescription, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Spinner } from "@/components/ui/spinner"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"

import app from "../../alwith.app.json"
import { authClient, loginPlatform, usePlatformAuth } from "./store"

type Mode = "code" | "password" | "register"
export function AuthGate({ children, auxiliary = false }: { children: ReactNode; auxiliary?: boolean }) {
  const authenticated = usePlatformAuth((s) => s.isAuthenticated)
  const loading = usePlatformAuth((s) => s.isLoading)
  if (loading)
    return (
      <div className="flex h-dvh items-center justify-center">
        <Spinner />
      </div>
    )
  if (authenticated) return children
  return auxiliary ? null : <PlatformLogin />
}

function PlatformLogin() {
  const { t } = useTranslation()
  const [mode, setMode] = useState<Mode>("code")
  const [email, setEmail] = useState("")
  const [code, setCode] = useState("")
  const [password, setPassword] = useState("")
  const [pendingAction, setPendingAction] = useState<"sendCode" | "submit" | null>(null)
  const busy = pendingAction !== null
  const [error, setError] = useState("")
  const [cooldowns, setCooldowns] = useState<Record<string, number>>({})
  const [now, setNow] = useState(Date.now())
  const cooldownKey = `${mode}:${email.trim().toLowerCase()}`
  const seconds = Math.max(0, Math.ceil(((cooldowns[cooldownKey] ?? 0) - now) / 1000))
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(timer)
  }, [])
  async function run(action: "sendCode" | "submit") {
    if (busy) return
    setPendingAction(action)
    setError("")
    try {
      await (action === "sendCode" ? sendCode() : submit())
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      setError(
        message === "WAITLISTED"
          ? t("platformAuth.waitlisted")
          : message === "DISABLED"
            ? t("platformAuth.disabled")
            : message || t("platformAuth.failed")
      )
    } finally {
      setPendingAction(null)
    }
  }
  async function sendCode() {
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) throw new Error(t("platformAuth.invalidEmail"))
    if (mode === "register" && (await authClient.emailExists(email.trim())).registered)
      throw new Error(t("platformAuth.registered"))
    await authClient.sendVerificationCode(email.trim(), mode === "register" ? "REGISTER" : "LOGIN")
    setCooldowns((current) => ({ ...current, [cooldownKey]: Date.now() + 60_000 }))
    setNow(Date.now())
  }
  async function submit() {
    if (mode === "register" && !isValidPassword(password)) throw new Error(t("platformAuth.passwordRule"))
    const response =
      mode === "register"
        ? await authClient.register(email.trim(), code.trim(), password)
        : mode === "password"
          ? await authClient.loginWithPassword(email.trim(), password)
          : await authClient.loginWithCode(email.trim(), code.trim())
    await loginPlatform(response)
  }
  return (
    <main className="flex h-dvh flex-col overflow-auto bg-background text-foreground">
      <div data-tauri-drag-region className="h-10 shrink-0" />
      <div className="m-auto flex w-full max-w-md flex-col gap-6 px-6 py-8">
        <header className="flex flex-col gap-2">
          <h1 className="text-xl font-semibold">{app.productName}</h1>
          <p className="text-sm text-muted-foreground">{t("platformAuth.intro")}</p>
        </header>
        <Tabs
          value={mode}
          onValueChange={(value) => {
            const mode: unknown = value
            if (mode !== "code" && mode !== "password" && mode !== "register") throw new Error("Invalid login mode")
            setMode(mode)
            setCode("")
            setPassword("")
            setError("")
          }}
        >
          <TabsList className="w-full">
            <TabsTrigger value="code" disabled={busy}>
              {t("platformAuth.codeLogin")}
            </TabsTrigger>
            <TabsTrigger value="password" disabled={busy}>
              {t("platformAuth.passwordLogin")}
            </TabsTrigger>
            <TabsTrigger value="register" disabled={busy}>
              {t("platformAuth.register")}
            </TabsTrigger>
          </TabsList>
        </Tabs>
        <form
          onSubmit={(event) => {
            event.preventDefault()
            void run("submit")
          }}
        >
          <FieldGroup>
            <Field data-disabled={busy}>
              <FieldLabel htmlFor="alwith-email">{t("platformAuth.email")}</FieldLabel>
              <Input
                id="alwith-email"
                type="email"
                autoComplete="email"
                required
                disabled={busy}
                value={email}
                onChange={(event) => setEmail(event.target.value)}
              />
            </Field>
            {mode !== "password" && (
              <Field data-disabled={busy}>
                <FieldLabel htmlFor="alwith-code">{t("platformAuth.code")}</FieldLabel>
                <div className="flex items-center gap-2">
                  <Input
                    id="alwith-code"
                    className="min-w-0 flex-1"
                    autoComplete="one-time-code"
                    required
                    disabled={busy}
                    value={code}
                    onChange={(event) => setCode(event.target.value)}
                  />
                  <Button
                    type="button"
                    variant="outline"
                    className="shrink-0"
                    disabled={busy || seconds > 0}
                    onClick={() => void run("sendCode")}
                  >
                    {pendingAction === "sendCode" && <Spinner data-icon="inline-start" />}
                    {seconds > 0 ? t("platformAuth.resend", { seconds }) : t("platformAuth.sendCode")}
                  </Button>
                </div>
              </Field>
            )}
            {mode !== "code" && (
              <Field data-disabled={busy}>
                <FieldLabel htmlFor="alwith-password">{t("platformAuth.password")}</FieldLabel>
                <Input
                  id="alwith-password"
                  type="password"
                  autoComplete={mode === "register" ? "new-password" : "current-password"}
                  required
                  disabled={busy}
                  value={password}
                  onChange={(event) => setPassword(event.target.value)}
                />
                {mode === "register" && <FieldDescription>{t("platformAuth.passwordRule")}</FieldDescription>}
              </Field>
            )}
            {error && (
              <Alert variant="destructive">
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            )}
            <Button type="submit" disabled={busy}>
              {pendingAction === "submit" && <Spinner data-icon="inline-start" />}
              {t(mode === "register" ? "platformAuth.register" : "platformAuth.signIn")}
            </Button>
          </FieldGroup>
        </form>
        <p className="text-xs text-muted-foreground">{t("platformAuth.independent")}</p>
      </div>
    </main>
  )
}

// Application wiring for the public auth client, transport and native refresh.
import {
  type AuthActions,
  type AuthState,
  type AuthStateEvent,
  authStoreName,
  createAuthClient,
  createAuthState,
  createTokenStorage,
  type LoginResponse
} from "@alwith/module-auth"
import { createTauriAuthRefresh } from "@alwith/module-auth/tauri"
import { invoke } from "@tauri-apps/api/core"
import { emit, listen } from "@tauri-apps/api/event"
import { fetch } from "@tauri-apps/plugin-http"
import { arch, platform } from "@tauri-apps/plugin-os"
import { create } from "zustand"

import { openStore } from "../store"
import { createAuthTransport } from "@alwith/module-auth/transport"
import { assertActiveLogin } from "@alwith/module-auth"

export const API_BASE_URL = import.meta.env.DEV ? "https://api-dev.alwith.ai/service" : "https://api.alwith.ai/service"
const STATE_EVENT = "alwith-auth-state"
const store = openStore(authStoreName(API_BASE_URL))
const storage = createTokenStorage({
  get: (key) => store.get(key),
  set: (key, value) => store.set(key, value),
  delete: (key) => store.delete(key)
})
const expiredListeners = new Set<() => void>()
const stateListeners = new Set<(event: AuthStateEvent) => void>()
const refreshTokens = createTauriAuthRefresh(invoke)
const transport = createAuthTransport({
  baseUrl: API_BASE_URL,
  fetch,
  storage,
  refresh: (refreshToken) => refreshTokens(API_BASE_URL, refreshToken),
  expired: async () => {
    for (const listener of expiredListeners) listener()
    await storage.clearAllAuth()
    await emit(STATE_EVENT, { action: "logout" } satisfies AuthStateEvent)
  }
})
export const authClient = createAuthClient({
  publicPost: (path, body) => transport.request(path, "POST", body, false),
  apiPost: (path, body) => transport.request(path, "POST", body),
  platform,
  arch,
  getDeviceId: storage.tokenStorage.getDeviceId,
  onLogoutError: () => console.warn("[auth] remote logout failed; clearing local login"),
  logInfo: () => {}
})
export const usePlatformAuth = create<AuthState & AuthActions>(
  createAuthState({
    storage,
    getProfile: () => transport.request("/api/v1/me/profile", "GET"),
    logoutApi: authClient.logoutApi,
    onInit: () => {},
    validateProfile: () => true,
    handleUnauthenticated: () => Promise.resolve(false),
    // ALwith login never alters Codex history, provider credentials or CLI login.
    loadProviders: () => {},
    clearProviders: () => {},
    onProfileRestored: () => {},
    clearAccountConversation: async () => {},
    onSignedIn: () => {},
    subscribeExpired: (listener) => expiredListeners.add(listener),
    subscribeState: (listener) => stateListeners.add(listener),
    broadcast: (event) => emit(STATE_EVENT, event)
  })
)

export async function loginPlatform(response: LoginResponse): Promise<void> {
  assertActiveLogin(response)
  await transport.invalidate()
  await usePlatformAuth.getState().login(response)
}

export async function logoutPlatform(): Promise<void> {
  await transport.invalidate()
  await usePlatformAuth.getState().logout()
}

/** Register the state listener before restoring credentials; called once at startup. */
export async function initPlatformAuth(): Promise<void> {
  await listen<AuthStateEvent>(STATE_EVENT, (event) => {
    for (const listener of stateListeners) listener(event.payload)
  })
  usePlatformAuth.getState().init()
}

export const platformApiRequest = <T>(path: string, method: "GET" | "POST", body?: unknown) => transport.request<T>(path, method, body)
